function updateHLL(hll, x) {
  const r = hash32(x);
  const idx = r >>> (32 - p);
  const w = (r << p) | (/* extra bits for rank */ 0);
  hll.registers[idx] = Math.max(hll.registers[idx], rank(w));
}
```

